func canFinish(numCourses int, prerequisites [][]int) bool {
	graph := make([][]int, numCourses)
	indeg := make([]int, numCourses)   // 还有几门先修课没上
	for _, p := range prerequisites {  // 先上 p[1] 才能上 p[0]
		graph[p[1]] = append(graph[p[1]], p[0])
		indeg[p[0]]++
	}
	q := []int{}
	for i := 0; i < numCourses; i++ {
		if indeg[i] == 0 {
			q = append(q, i)
		}
	}
	done := 0
	for len(q) > 0 {
		b := q[0]
		q = q[1:]
		done++
		for _, a := range graph[b] {
			indeg[a]--
			if indeg[a] == 0 { // 先修课都上完了
				q = append(q, a)
			}
		}
	}
	return done == numCourses // 环上的课永远上不了
}

